class Solution:
    def minCostToSplitIntoOnes(self, n):
        cost = [0] * (n + 1)
        for x in range(2, n + 1):
            cost[x] = min(a * (x - a) + cost[a] + cost[x - a] for a in range(1, x // 2 + 1))
        return cost[n]

