    long long minCostToSplitIntoOnes(int n) {
        vector<long long> cost(n + 1, 0);
        for (int x = 2; x <= n; x++) {
            long long best = LLONG_MAX;
            for (int a = 1; a <= x / 2; a++)
                best = min(best, (long long)a * (x - a) + cost[a] + cost[x - a]);
            cost[x] = best;
        }
        return cost[n];
    }
};

