class Solution {
    public long minCostToSplitIntoOnes(int n) {
        long[] cost = new long[n + 1];
        for (int x = 2; x <= n; x++) {
            long best = Long.MAX_VALUE;
            for (int a = 1; a <= x / 2; a++)
                best = Math.min(best, (long) a * (x - a) + cost[a] + cost[x - a]);
            cost[x] = best;
        }
        return cost[n];
    }
}

