var minCostToSplitIntoOnes = function(n) {
    const cost = new Array(n + 1).fill(0);
    for (let x = 2; x <= n; x++) {
        let best = Infinity;
        for (let a = 1; a <= x >> 1; a++)
            best = Math.min(best, a * (x - a) + cost[a] + cost[x - a]);
        cost[x] = best;
    }
    return cost[n];
};
